-- S6: 25 candidatas MIGRAR, prioridad SECURITY -> PAYMENTS_CHECKOUT -> TRANSITIONS -> OFFERS_INSTALLMENTS.
-- 11 + 8 + 4 + 2; 200 vectores. Solo propuestas. Sin juicio/promoción, bridge, IG ni deprecaciones.
BEGIN;
DO $pre$ BEGIN
 IF (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='VIGENTE')<>128
  OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>14
  OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0
  OR (SELECT count(*) FROM lf_ops.reglas) NOT IN (215,586)
  OR ((SELECT count(*) FROM lf_ops.reglas)=586 AND
    (SELECT count(distinct legacy_id) FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA')<>108)
 THEN RAISE EXCEPTION 'S6_BASELINE_DRIFT'; END IF;
END $pre$;
