  cd:=p->>'codigo';
  q:=lf_ops.nucleo_regla_proponer_v1(p,false);
  IF q->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (q->>'bloqueantes')::int<>0
  THEN RAISE EXCEPTION 'S6_PREFLIGHT_FAIL % %',cd,q; END IF;
  q:=lf_ops.nucleo_regla_proponer_v1(p,true);
  IF q->>'resultado'<>'CANDIDATA' OR (q->>'version')::int<>1
  THEN RAISE EXCEPTION 'S6_CREATE_FAIL % %',cd,q; END IF;
  IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8 OR
     (SELECT count(distinct entrada::text) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8
  THEN RAISE EXCEPTION 'S6_VECTOR_INVALID %',cd; END IF;
  e:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
  IF e->>'decision'<>'BLOQUEADA' OR e->>'hash_paquete' IS NULL
  THEN RAISE EXCEPTION 'S6_GATE_FAIL % %',cd,e; END IF;
  n:=n+1;
  RAISE NOTICE 'S6_CANDIDATE % eval=% hash=%',cd,e->>'evaluacion_id',e->>'hash_paquete';
 END LOOP;
 IF n<>25 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>39
   OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='VIGENTE')<>128
   OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla LIKE 'S6-C%')<>200
   OR (SELECT count(*) FROM lf_ops.nucleo_juicios WHERE regla LIKE 'S6-C%')<>0
   OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla LIKE 'S6-C%' AND estado='PUBLICADA')<>0
   OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.reglas r) IS DISTINCT FROM before_legacy
   OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY legacy_id,nucleo_codigo,version_nucleo) FROM lf_ops.lf_nucleo_cobertura_legada r) IS DISTINCT FROM before_bridge
   OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones r) IS DISTINCT FROM before_dep
 THEN RAISE EXCEPTION 'S6_FINAL_READBACK_FAILED'; END IF;
 RAISE NOTICE 'S6_PASS 25 CANDIDATAS, 200 PRUEBAS, 0 JUECES, 0 PROMOCIONES';
END $create$;
COMMIT;